#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[1111111];
signed main() {
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
    cin>>n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    int ans=0;
    stack<int>s;
    for (int i=1;i<=n;i++) {
        while(!s.empty()&&a[s.top()]<=a[i]){
            s.pop();
            ans++;
        }
        s.push(i);
    }
    cout<<ans;
	return 0;
}
